custom/backend/host.ts.content:
import {mutation,query} from "./_generated/server";
import {v,ConvexError} from "convex/values";
const owner=async(ctx:any)=>{const i=await ctx.auth.getUserIdentity();if(!i||i.issuer!=="https://unrelated-task08-host.example")throw new ConvexError("HOST_AUTH_REQUIRED");return i.subject;};
export const seed=mutation({args:{text:v.string()},handler:async(ctx,args)=>{const subject=await owner(ctx);const row=await ctx.db.query("hostNotes").withIndex("by_owner",q=>q.eq("owner",subject)).unique();if(row)return {noteId:row._id};return {noteId:await ctx.db.insert("hostNotes",{owner:subject,text:args.text})};}});
export const authenticated=query({args:{},handler:async(ctx)=>{const subject=await owner(ctx);return ctx.db.query("hostNotes").withIndex("by_owner",q=>q.eq("owner",subject)).collect();}});

